// Fixed probe reports only. Avoid System.Web initialization in the restricted guest.
using System;using System.Text;using System.Collections;using System.Reflection;using System.Globalization;
internal sealed class LpacProbeJson {
    internal string Serialize(object value){var output=new StringBuilder();Write(output,value,0);return output.ToString();}
    static void String(StringBuilder output,string text){output.Append('"');foreach(char c in text){switch(c){case '"':output.Append("\\\"");break;case '\\':output.Append("\\\\");break;case '\n':output.Append("\\n");break;case '\r':output.Append("\\r");break;case '\t':output.Append("\\t");break;default:if(c<32)output.Append("\\u"+((int)c).ToString("x4",CultureInfo.InvariantCulture));else output.Append(c);break;}}output.Append('"');}
    static void Write(StringBuilder output,object value,int depth){if(depth>16)throw new InvalidOperationException("PROBE_JSON_DEPTH");if(value==null){output.Append("null");return;}if(value is string){String(output,(string)value);return;}if(value is bool){output.Append((bool)value?"true":"false");return;}var type=value.GetType();if(type==typeof(int)||type==typeof(uint)||type==typeof(long)||type==typeof(ulong)||type==typeof(short)||type==typeof(ushort)||type==typeof(byte)||type==typeof(sbyte)){output.Append(Convert.ToString(value,CultureInfo.InvariantCulture));return;}
        var dictionary=value as IDictionary;if(dictionary!=null){output.Append('{');bool first=true;foreach(DictionaryEntry item in dictionary){if(!(item.Key is string))throw new InvalidOperationException("PROBE_JSON_KEY");if(!first)output.Append(',');first=false;String(output,(string)item.Key);output.Append(':');Write(output,item.Value,depth+1);}output.Append('}');return;}
        var list=value as IEnumerable;if(list!=null){output.Append('[');bool first=true;foreach(var item in list){if(!first)output.Append(',');first=false;Write(output,item,depth+1);}output.Append(']');return;}
        if(type.IsPrimitive||type.IsEnum)throw new InvalidOperationException("PROBE_JSON_TYPE");output.Append('{');bool initial=true;foreach(var property in type.GetProperties(BindingFlags.Public|BindingFlags.Instance)){if(property.GetIndexParameters().Length!=0||!property.CanRead)throw new InvalidOperationException("PROBE_JSON_PROPERTY");if(!initial)output.Append(',');initial=false;String(output,property.Name);output.Append(':');Write(output,property.GetValue(value,null),depth+1);}output.Append('}');
    }
}
